: "diamond", "oa_url": "https://direct.mit.edu/tacl/article-pdf/doi/10.1162/tacl_a_00752/2535122/tacl_a_00752.pdf", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1162/tacl_a_00752", "doi": "https://doi.org/10.1162/tacl_a_00752", "is_oa": true, "landing_page_url": "https://doi.org/10.1162/tacl_a_00752", "pdf_url": "https://direct.mit.edu/tacl/article-pdf/doi/10.1162/tacl_a_00752/2535122/tacl_a_00752.pdf", "source": {"id": "https://openalex.org/S2729999759", "display_name": "Transactions of the Association for Computational Linguistics", "issn_l": "2307-387X", "issn": ["2307-387X"], "is_oa": true, "is_in_doaj": true, "is_core": true, "listed_in": ["ccf-b", "cwts-core", "doaj", "dongbi-b", "jufo-1", "norway-2", "poland-20", "russia-white-list-1"], "host_organization": "https://openalex.org/P4310320244", "host_organization_name": "Association for Computational Linguistics", "host_organization_lineage": ["https://openalex.org/P4310320244"], "host_organization_lineage_names": ["Association for Computational Linguistics"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Transactions of the Association for Computational Linguistics", "raw_type": "journal-article"}, "abstract": "Abstract How do people understand and evaluate claims about others’ beliefs, even though these beliefs cannot be directly observed? In this paper, we introduce a cognitive model of epistemic language interpretation, grounded in Bayesian inferences about other agents’ goals, beliefs, and intentions: a language-augmented Bayesian theory-of-mind (LaBToM). By translating natural language into an epistemic “language-of-thought” with grammar-constrained LLM decoding, then evaluating these translations against the inferences produced by inverting a generative model of rational action and perception, LaBToM captures graded plausibility judgments of epistemic claims. We validate our model in an experiment where participants watch an agent navigate a maze to find keys hidden in boxes needed to reach their goal, then rate sentences about the agent’s beliefs. In contrast with multimodal LLMs (GPT-4o, Gemini Pro) and ablated models, our model correlates highly with human judgments for a wide range of expressions, including modal language, uncertainty expressions, knowledge claims, likelihood comparisons, and attributions of false belief."}]", "excerpt_truncated": true, "source_sha256": "a07fb253e6a4e73ac7dde93112cab4f8a3d285588a6590d158f63afd5ffd3aa0", "verification_required": true, "topic_domain": "question_abandonment", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.62311/nesx/rb-978-81-997569-7-7", "doi:10.1162/tacl_a_00752/2535122/tacl_a_00752.pdf", "doi:10.1162/tacl_a_00752", "openalex:W7128917653"], "source_candidates": ["https://doi.org/10.62311/nesx/rb-978-81-997569-7-7", "https://direct.mit.edu/tacl/article-pdf/doi/10.1162/tacl_a_00752/2535122/tacl_a_00752.pdf", "https://doi.org/10.1162/tacl_a_00752"], "source_candidate_identities": {}}
